tasks.prompt:
I have no coding background. Another AI made this small reading-list page for me. Please change it so I can rename a saved book and mark a book as read or unread. Keep the existing Add feature and keep every saved book; do not change the storage key or make me transfer my list by hand. Make the technical decisions and give me the complete replacement file plus simple instructions for replacing the old file. Do not give me a JavaScript lesson. Here is the current complete file:

<!doctype html>
<html lang="en">
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Reading list</title>
<h1>Reading list</h1>
<label>Book title <input id="title"></label>
<button id="add">Add</button>
<ul id="books"></ul>
<script>
const KEY = "reading-list-v1";
let books = JSON.parse(localStorage.getItem(KEY) || "[]");
function save() { localStorage.setItem(KEY, JSON.stringify(books)); }
function render() {
  const list = document.getElementById("books");
  list.replaceChildren();
  books.forEach(book => {
    const li = document.createElement("li");
    const label = document.createElement("span");
    label.textContent = book.title + (book.read ? " — read" : " — not read");
    const button = document.createElement("button");
    button.textContent = "Mark read";
    button.onclick = () => { book.read = true; save(); render(); };
    li.append(label, button);
    list.append(li);
  });
}
document.getElementById("add").onclick = () => {
  const title = document.getElementById("title").value.trim();
  if (title) { books.push({ id: Date.now(), title, read: false }); save(); render(); }
};
render();
</script>
</html>

The existing list is important to me. Preserve it. If you see a risk to saved data, explain it briefly and choose the safest practical way to make the change.

I do not know how to code. I asked another AI to make this list for me. The items disappear when I close the browser, and I want them to stay. I already have entries in the current list, so do not just tell me to start again. Please fix the file so future entries survive closing and reopening the browser, and move the existing entries safely into the new saving method. Keep Add and Remove working. Give me the full replacement file and very simple instructions. Do not claim you have tested it unless you actually ran it. Here is the current file:

<!doctype html>
<html lang="en">
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>My list</title>
<h1>My list</h1>
<label>New item <input id="item"></label>
<button id="add">Add</button>
<ul id="items"></ul>
<script>
const KEY = "my-list-v1";
let items = JSON.parse(sessionStorage.getItem(KEY) || "[]");
function save() { sessionStorage.setItem(KEY, JSON.stringify(items)); }
function render() {
  const list = document.getElementById("items");
  list.replaceChildren();
  items.forEach((item, index) => {
    const li = document.createElement("li");
    const text = document.createElement("span");
    text.textContent = item;
    const remove = document.createElement("button");
    remove.textContent = "Remove";
    remove.onclick = () => { items.splice(index, 1); save(); render(); };
    li.append(text, remove);
    list.append(li);
  });
}
document.getElementById("add").onclick = () => {
  const value = document.getElementById("item").value.trim();
  if (value) { items.push(value); save(); render(); }
};
render();
</script>
</html>

For the migration, do not discard the old session list until its contents have been successfully copied to the persistent location. If a non-empty persistent list already exists, do not silently overwrite either list; explain the situation and use a safe approach.
